use vstd::prelude::*;

verus! {
    fn solve(input: Vec<char>) -> Vec<char>
        // Preconditions on the concrete vector length and on its logical view `input@`
        requires
            input.len() >= 3,
            input@[1] == ' ',
            (input@[0] == 'H' || input@[0] == 'D'),
            (input@[2] == 'H' || input@[2] == 'D'),
            // if there is a fourth character, it must be '\n'
            if input.len() > 3 { input@[3] == '\n' } else { true },
        // Postcondition: we return exactly two chars,
        // second is newline, first is 'H' iff input[0]==input[2], else 'D'
        ensures |res: Vec<char>| {
            res.len() == 2 &&
            res@[1] == '\n' &&
            if input@[0] == input@[2] {
                res@[0] == 'H'
            } else {
                res@[0] == 'D'
            }
        }
    {
        // Read the first and third characters
        let first = input[0];
        let third = input[2];
        // Decide output character
        let out_char = if first == third { 'H' } else { 'D' };

        // Build the result vector
        let mut res = Vec::new();
        res.push(out_char);
        res.push('\n');
        res
    }
}

